def all_canonical_exercises() -> List[CanonicalExercise]:
    return _CANONICAL


def canonical_display_name(exercise_db_id: Optional[str]) -> Optional[str]:
    """Return canonical Title Case name for an ExerciseDB id."""
    for c in _CANONICAL:
        if c.exercise_db_id == exercise_db_id:
            return c.name
    return None


# Legacy compatibility

_KEYWORD_MAP: Dict[str, CanonicalExercise] = {}
for _c in _CANONICAL:
    for _kw in _c.match:
        _KEYWORD_MAP[_kw] = _c


def _canonical_name(name: str) -> Optional[CanonicalExercise]:
    """Match a raw exercise name against canonical keywords."""
    name_lower = name.lower()
    # Sort keywords longest-first for greedy matching
    sorted_keywords = sorted(_KEYWORD_MAP.items(), key=lambda kv: len(kv[0]), reverse=True)
    for kw, canonical in sorted_keywords:
        if kw in name_lower:
            return canonical
    # Substring containment fallback
    for kw, canonical in sorted_keywords:
        if name_lower in kw or kw in name_lower:
            return canonical
    return None